<?php
declare(strict_types=1);require __DIR__.'/../app/bootstrap.php';require_login();$no=preg_replace('/[^0-9]/','',(string)($_GET['asset_no']??''));if(!preg_match('/^\d{7}$/',$no)){http_response_code(400);exit('شماره اموال نامعتبر است.');}$q=db()->prepare('SELECT a.*,p.full_name personnel_name,p.personnel_code FROM assets a LEFT JOIN personnel p ON p.id=a.personnel_id WHERE a.asset_no=?');$q->execute([$no]);$a=$q->fetch();if(!$a){http_response_code(404);exit('تجهیز یافت نشد.');}$q=db()->prepare('SELECT * FROM asset_disks WHERE asset_no=? ORDER BY disk_index');$q->execute([$no]);$disks=$q->fetchAll();$q=db()->prepare('SELECT * FROM asset_ram_slots WHERE asset_no=? ORDER BY slot_no');$q->execute([$no]);$rams=$q->fetchAll();$q=db()->prepare('SELECT * FROM usage_stats WHERE asset_no=?');$q->execute([$no]);$usageRow=$q->fetch()?:[];$q=db()->prepare('SELECT al.*,u.full_name FROM audit_logs al LEFT JOIN users u ON u.id=al.user_id WHERE al.entity_type=? AND al.entity_id=? ORDER BY al.id DESC LIMIT 20');$q->execute(['asset',$no]);$history=$q->fetchAll();$t=json_decode((string)$a['technical'],true);$t=is_array($t)?$t:[];$types=['computer'=>'کامپیوتر','printer'=>'چاپگر','scanner'=>'اسکنر','display'=>'نمایشگر'];$status=['active'=>'فعال','repair'=>'تعمیر','retired'=>'اسقاط','lost'=>'مفقود'];$labels=['ComputerName'=>'نام کامپیوتر','UserName'=>'کاربر','Manufacturer'=>'سازنده','Model'=>'مدل','SystemType'=>'نوع سیستم','SystemSerial'=>'سریال','SystemUUID'=>'UUID','Domain'=>'دامین / Workgroup','OSName'=>'سیستم‌عامل','OSVersion'=>'نسخه','OSBuild'=>'Build','OSArchitecture'=>'معماری','CPUName'=>'پردازنده','CPUManufacturer'=>'سازنده CPU','CPUCores'=>'هسته','CPULogicalProcessors'=>'پردازنده منطقی','CPUMaxClockMHz'=>'فرکانس MHz','RAMTotalGB'=>'RAM کل GB','RAMSlotCount'=>'اسلات RAM','RAMInstalledSlots'=>'اسلات‌های پر','RAMType'=>'نوع RAM','MotherboardManufacturer'=>'سازنده مادربرد','MotherboardProduct'=>'مدل مادربرد','MotherboardVersion'=>'نسخه مادربرد','MotherboardSerial'=>'سریال مادربرد','BIOSManufacturer'=>'سازنده BIOS','BIOSVersion'=>'نسخه BIOS','BIOSSerial'=>'سریال BIOS','BIOSReleaseDate'=>'تاریخ BIOS','LogicalDriveDetails'=>'درایوهای منطقی','NetworkDetails'=>'جزئیات کامل شبکه','GPUDetails'=>'GPU','SoundDetails'=>'صدا','PageFileDetails'=>'Page File','AntivirusDetails'=>'آنتی‌ویروس','PrinterType'=>'نوع چاپگر','PrinterCapabilities'=>'قابلیت‌ها','ColorMode'=>'رنگی/سیاه‌وسفید','Connection'=>'اتصال','NetworkSharing'=>'اشتراک شبکه','Duplex'=>'چاپ دورو','DisplayTechnology'=>'فناوری نمایشگر','DisplaySize'=>'اندازه','DisplayResolution'=>'رزولوشن','DisplaySerial'=>'سریال','ScannerType'=>'نوع اسکنر','ScannerResolution'=>'رزولوشن','ScannerConnection'=>'اتصال','ScannerDuplex'=>'اسکن دورو','IPAddresses'=>'IP'];$sections=['computer'=>['سیستم و کاربر'=>['ComputerName','UserName','Manufacturer','Model','SystemType','SystemSerial','SystemUUID','Domain'],'سیستم‌عامل'=>['OSName','OSVersion','OSBuild','OSArchitecture'],'پردازنده'=>['CPUName','CPUManufacturer','CPUCores','CPULogicalProcessors','CPUMaxClockMHz'],'مادربرد'=>['MotherboardManufacturer','MotherboardProduct','MotherboardVersion','MotherboardSerial'],'BIOS'=>['BIOSManufacturer','BIOSVersion','BIOSSerial','BIOSReleaseDate'],'شبکه'=>['NetworkDetails'],'تجهیزات جانبی'=>['GPUDetails','SoundDetails','PageFileDetails','AntivirusDetails']],'printer'=>['مشخصات چاپگر'=>['PrinterType','PrinterCapabilities','ColorMode','Connection','NetworkSharing','Duplex','IPAddresses']],'scanner'=>['مشخصات اسکنر'=>['ScannerType','ScannerResolution','ScannerConnection','ScannerDuplex','IPAddresses']],'display'=>['مشخصات نمایشگر'=>['MonitorDetails','DisplayTechnology','DisplaySize','DisplayResolution','DisplaySerial','Connection']]];$usage=['boot_count'=>'تعداد بوت','normal_shutdown_count'=>'خاموشی عادی','unexpected_shutdown_count'=>'خاموشی غیرمنتظره / کرش','user_shutdown_count'=>'خاموشی کاربر','last_boot_time'=>'آخرین روشن‌شدن','last_shutdown_time'=>'آخرین خاموش‌شدن','completed_session_count'=>'جلسات کامل','current_session_hours'=>'جلسه فعلی (ساعت)','current_session_duration'=>'مدت جلسه فعلی','total_usage_hours'=>'کل استفاده (ساعت)','total_usage_duration'=>'کل مدت استفاده','average_session_hours'=>'میانگین جلسه (ساعت)','average_session_duration'=>'میانگین مدت جلسه','longest_session_hours'=>'طولانی‌ترین جلسه (ساعت)','longest_session_duration'=>'طولانی‌ترین جلسه','collected_at'=>'تاریخ ثبت اطلاعات'];function showv(mixed $v):string{return is_array($v)?implode('، ',array_map('strval',$v)):(string)$v;}function hv(array $t,string $k):bool{return isset($t[$k])&&((is_array($t[$k])&&$t[$k])||(!is_array($t[$k])&&trim((string)$t[$k])!==''));}
?><!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($no)?> | پرونده تجهیز</title><link rel="stylesheet" href="assets/app.css"></head><body><header><a class="brand" href="index.php">HWiNFO · پایش سخت‌افزار</a><nav><a href="index.php">داشبورد</a><a href="assets.php">تجهیزات</a><a href="report.php">گزارش‌ها</a><a href="logout.php">خروج</a></nav></header><main><div class="page-head"><div><div class="eyebrow">پرونده تجهیز</div><h1><?=e($no)?></h1><p class="muted"><?=e($types[$a['asset_type']]??$a['asset_type'])?> · <?=e($a['updated_at'])?></p></div><div class="actions"><?php if($a['source_file']):?><a class="btn" href="source_download.php?asset_no=<?=urlencode($no)?>">CSV منبع</a><?php endif;?><?php if(can_manage_asset_type($a['asset_type'],'edit')):?><a class="btn primary" href="asset_edit.php?asset_no=<?=urlencode($no)">ویرایش</a><?php endif;?></div></div><section class="asset-summary"><div class="asset-title"><span class="asset-icon"><?=e(mb_substr($types[$a['asset_type']]??'ت',0,1))?></span><div><strong><?=e(trim(($a['manufacturer']??'').' '.($a['model']??''))?:'بدون مدل')?></strong><span><?=e($a['hostname']?:'—')?></span></div></div><div class="summary-item"><span>مسئول</span><b><?=e($a['personnel_name']?:($t['UserName']??'—'))?></b></div><div class="summary-item"><span>مکان</span><b><?=e($a['location']?:'—')?></b></div><div class="summary-item"><span>وضعیت</span><b class="badge <?=e($a['status'])?>"><?=e($status[$a['status']]??$a['status'])?></b></div></section><section class="panel"><h2>مشخصات پایه</h2><div class="info-grid"><div><span>شماره اموال</span><strong><?=e($a['asset_no'])?></strong></div><div><span>نوع</span><strong><?=e($types[$a['asset_type']]??$a['asset_type'])?></strong></div><div><span>نام دستگاه</span><strong><?=e($a['hostname']?:($t['ComputerName']??'—'))?></strong></div><div><span>سریال</span><strong><?=e($a['serial_no']?:($t['SystemSerial']??'—'))?></strong></div><div><span>پرسنل</span><strong><?=e($a['personnel_name']?:'—')?></strong></div><div><span>مکان</span><strong><?=e($a['location']?:'—')?></strong></div></div></section><?php foreach(($sections[$a['asset_type']]??[]) as $title=>$keys):$vis=array_filter($keys,fn($k)=>hv($t,$k));if(!$vis)continue;?><section class="panel"><h2><?=e($title)?></h2><div class="technical-grid"><?php foreach($vis as $k):?><div class="technical-item"><span><?=e($labels[$k]??$k)?></span><strong><?=e(showv($t[$k]))?></strong></div><?php endforeach;?></div></section><?php endforeach;?><?php if($a['asset_type']==='computer'):?><section class="panel"><h2>دیسک‌های فیزیکی</h2><div class="table-wrap"><table><thead><tr><th>#</th><th>مدل</th><th>GB</th><th>سریال</th><th>Interface</th><th>Media</th></tr></thead><tbody><?php foreach($disks as $d):?><tr><td><?=e($d['disk_index'])?></td><td><?=e($d['model'])?></td><td><?=e($d['size_gb'])?></td><td><?=e($d['serial_no'])?></td><td><?=e($d['interface_name'])?></td><td><?=e($d['media'])?></td></tr><?php endforeach;?></tbody></table></div></section><section class="panel"><h2>ماژول‌های RAM</h2><div class="table-wrap"><table><thead><tr><th>اسلات</th><th>وضعیت</th><th>GB</th><th>نوع</th><th>MHz</th><th>سازنده</th><th>Part</th><th>سریال</th></tr></thead><tbody><?php foreach($rams as $r):?><tr><td><?=e($r['slot_no'])?></td><td><?=e($r['state'])?></td><td><?=e($r['capacity_gb'])?></td><td><?=e($r['ram_type'])?></td><td><?=e($r['speed_mhz'])?></td><td><?=e($r['manufacturer'])?></td><td><?=e($r['part_number'])?></td><td><?=e($r['serial_no'])?></td></tr><?php endforeach;?></tbody></table></div></section><section class="panel"><h2>آمار استفاده و تاریخ ثبت اطلاعات</h2><div class="technical-grid"><?php foreach($usage as $k=>$label):if(!array_key_exists($k,$usageRow)||$usageRow[$k]===null||$usageRow[$k]==='')continue;?><div class="technical-item"><span><?=e($label)?></span><strong><?=e((string)$usageRow[$k])?></strong></div><?php endforeach;?></div></section><?php endif;?><section class="panel"><h2>سابقه ثبت و تغییرات</h2><div class="table-wrap"><table><thead><tr><th>کاربر ثبت‌کننده</th><th>IP</th><th>زمان ثبت/تغییر</th><th>عملیات</th><th>CollectedAt</th></tr></thead><tbody><?php foreach($history as $h):$detail=json_decode((string)$h['details'],true)?:[];?><tr><td><?=e($h['full_name']??'سیستم')?></td><td><?=e($h['ip_address']??'—')?></td><td><?=e($h['created_at'])?></td><td><?=e($h['action'])?></td><td><?=e((string)($detail['collected_at']??'—'))?></td></tr><?php endforeach;?><?php if(!$history):?><tr><td colspan="5" class="empty">سابقه‌ای ثبت نشده است.</td></tr><?php endif;?></tbody></table></div></section></main></body></html>
